import React from 'react';
import ClubLogo from './ClubLogo';

export default function ClubModal({ club, joinedClubs, onJoin, onClose }) {
  if (!club) return null;
  const isJoined = joinedClubs.includes(club.id);

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-card" onClick={(e) => e.stopPropagation()}>
        <button className="modal-close" onClick={onClose} aria-label="Close">
          &#x2715;
        </button>
        <div className="modal-header">
          <ClubLogo club={club} size={64} />
          <div className="modal-title-group">
            <h2 className="modal-club-name">{club.name}</h2>
            <span className="modal-category-badge">{club.category}</span>
          </div>
        </div>
        <div className="modal-body">
          <div className="modal-stat">
            <span className="modal-stat-label">Members</span>
            <span className="modal-stat-value">{club.memberCount}</span>
          </div>
          <p className="modal-description">{club.description}</p>
          <button
            className={`join-btn${isJoined ? ' joined' : ''}`}
            onClick={() => onJoin(club.id)}
          >
            {isJoined ? 'Joined ✓' : 'Join Club'}
          </button>
        </div>
      </div>
    </div>
  );
}
